def extract_hwpx(src_hwpx: str, extract_dir: str) -> None:
    if os.path.exists(extract_dir):
        shutil.rmtree(extract_dir)
    os.makedirs(extract_dir, exist_ok=True)

    with zipfile.ZipFile(src_hwpx, "r") as z:
        z.extractall(extract_dir)


def make_hwpx(extract_dir: str, out_hwpx: str) -> None:
    if os.path.exists(out_hwpx):
        os.remove(out_hwpx)

    # Walk and add files with stable ordering.
    all_files = []
    for root, dirs, files in os.walk(extract_dir):
        dirs.sort()
        files.sort()
        for f in files:
            p = os.path.join(root, f)
            rel = os.path.relpath(p, extract_dir)
            all_files.append((rel, p))

    with zipfile.ZipFile(out_hwpx, "w") as z:
        # Some formats require 'mimetype' first and uncompressed.
        mimetype = next((p for rel, p in all_files if rel == "mimetype"), None)
        if mimetype is not None:
            z.write(mimetype, arcname="mimetype", compress_type=zipfile.ZIP_STORED)

        for rel, p in all_files:
            if rel == "mimetype":
                continue
            z.write(p, arcname=rel, compress_type=zipfile.ZIP_DEFLATED)


