def die(msg: str) -> None:
    print(f"ERROR: {msg}", file=sys.stderr)
    sys.exit(1)


def _localname(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def extract_root_namespaces(xml_path: str) -> list[tuple[str, str]]:
    """Extract xmlns declarations from the root element text using regex.

    Returns list of (prefix, uri) where prefix may be '' for default ns.
    """
    raw = open(xml_path, "rb").read()
    # Grab up through first '>' after the first '<' that starts the root.
    # This is sufficient for our inputs and avoids parsing before registering.
    m = re.search(br"<[^!?][^>]*>", raw)
    if not m:
        return []
    root_tag = m.group(0).decode("utf-8", errors="replace")

    decls: list[tuple[str, str]] = []
    # default namespace
    for uri in re.findall(r'\sxmlns="([^"]+)"', root_tag):
        decls.append(("", uri))
    # prefixed namespaces
    for prefix, uri in re.findall(r'\sxmlns:([A-Za-z_][\w\-.]*)="([^"]+)"', root_tag):
        decls.append((prefix, uri))
    return decls


