    for child in list(p):
        ln = _localname(child.tag)
        if ln.lower() in {"linesegarray", "lineseg", "linesegarr"} or ln in {"lineSegArray", "lineSeg"}:
            p.remove(child)
            removed = True

    # Also remove any stray nested cache tags that might remain.
    for parent in list(p.iter()):
        for child in list(parent):
            ln = _localname(child.tag)
            if ln.lower() in {"linesegarray", "lineseg"} or ln in {"lineSegArray"}:
                parent.remove(child)
                removed = True

    return removed


def replace_text_everywhere(root: ET.Element, replacements: list[tuple[str, str]]) -> set[int]:
    """Replace text in all elements' .text/.tail.

    Returns set of paragraph ids (int) that were modified.
    """
    modified_para_ids: set[int] = set()

    # Precompute parent map so we can ascend from a text node to its paragraph.
    parent: dict[ET.Element, ET.Element] = {}
    for p in root.iter():
        for c in list(p):
            parent[c] = p

    def find_para_id(el: ET.Element) -> int | None:
        cur = el
        while cur is not None:
            if cur.tag == f"{{{HP_NS}}}p" and "id" in cur.attrib:
                try:
                    return int(cur.attrib["id"])
                except Exception:
                    return None
            cur = parent.get(cur)
        return None

    for el in root.iter():
        for attr in ("text", "tail"):
            s = getattr(el, attr)
            if not s or not s.strip():
                continue
            if APPENDIX_SENTENCE in s:
                continue

            new_s = s
            for old, new in replacements:
                if old and old in new_s:
                    new_s = new_s.replace(old, new)
            if new_s != s:
                setattr(el, attr, new_s)
                pid = find_para_id(el)
                if pid is not None:
                    modified_para_ids.add(pid)

    return modified_para_ids


def iter_paragraphs(root: ET.Element) -> list[ET.Element]:
    return list(root.iter(f"{{{HP_NS}}}p"))


def extract_table_kv(root: ET.Element) -> dict[str, str]:
    """Extract key/value pairs from 2-column tables where left cell is label."""
    out: dict[str, str] = {}
    for tr in root.iter(f"{{{HP_NS}}}tr"):
        tcs = [tc for tc in tr if tc.tag == f"{{{HP_NS}}}tc"]
        if len(tcs) < 2:
            continue

        def tc_text(tc: ET.Element) -> str:
            # Gather all hp:t text under this cell.
            return "".join((t.text or "") for t in tc.iter(f"{{{HP_NS}}}t"))

        left = tc_text(tcs[0]).strip()
        right = tc_text(tcs[1]).strip()
        if left and right:
            out[left] = right
    return out


def find_paragraph_by_contains(root: ET.Element, needle: str) -> list[ET.Element]:
    hits: list[ET.Element] = []
    for p in root.iter(f"{{{HP_NS}}}p"):
        if needle in paragraph_full_text(p):
            hits.append(p)
    return hits


def load_updates() -> dict:
    import json

    with open(UPDATE_JSON, "r", encoding="utf-8") as f:
        return json.load(f)


def load_followups() -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    with open(FOLLOWUPS_CSV, "r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for r in reader:
            rows.append(r)

    def seq_key(r: dict[str, str]) -> int:
        try:
            return int((r.get("sequence") or "").strip())
        except Exception:
            return 10**9

    rows.sort(key=seq_key)
    return rows


def update_section_xml(xml_path: str, updates: dict, followups_rows: list[dict[str, str]] | None) -> None:
    register_namespaces_from_root(xml_path)
    tree = ET.parse(xml_path)
    root = tree.getroot()

    # Extract OLD values from the current document (per instruction: do not guess).
    old_customer = None
    old_owner = None
    old_window = None
    old_note = None

    customer_ps = find_paragraph_by_contains(root, "고객사:")
    if customer_ps:
        t = paragraph_full_text(customer_ps[0])
        old_customer = t.split("고객사:", 1)[1].strip()

    owner_ps = find_paragraph_by_contains(root, "현 담당자:")
    if owner_ps:
        t = paragraph_full_text(owner_ps[0])
        old_owner = t.split("현 담당자:", 1)[1].strip()

    window_ps = find_paragraph_by_contains(root, "갱신 윈도우:")
    if window_ps:
        t = paragraph_full_text(window_ps[0])
        old_window = t.split("갱신 윈도우:", 1)[1].strip()

    note_ps = find_paragraph_by_contains(root, "가격 메모:")
    if note_ps:
        t = paragraph_full_text(note_ps[0])
        old_note = t.split("가격 메모:", 1)[1].strip()

    table_kv = extract_table_kv(root)
    old_band = table_kv.get("가격 밴드")
    old_escalation = table_kv.get("에스컬레이션 연락처")

    new_window = f"{updates['window_start']} ~ {updates['window_end']}"

    # Global replacements (catch all occurrences).
    replacements: list[tuple[str, str]] = []
    if old_owner:
        replacements.append((old_owner, updates["owner_name"]))
    if old_window:
        replacements.append((old_window, new_window))
    if old_band:
        replacements.append((old_band, updates["band"]))
    if old_escalation:
        replacements.append((old_escalation, updates["escalation_email"]))
    if old_note:
        replacements.append((old_note, updates["note"]))
    if old_customer:
        replacements.append((old_customer, updates["customer"]))

    modified_para_ids = replace_text_everywhere(root, replacements)

    # Label-specific paragraph normalization (handles split runs and ensures exact formatting).
    for p in root.iter(f"{{{HP_NS}}}p"):
        full = paragraph_full_text(p)
        if APPENDIX_SENTENCE in full:
            continue

        if "고객사:" in full:
            if set_paragraph_text(p, f"고객사: {updates['customer']}"):
                try:
                    modified_para_ids.add(int(p.attrib.get("id", "-1")))
                except Exception:
                    pass
        if "현 담당자:" in full:
            if set_paragraph_text(p, f"현 담당자: {updates['owner_name']}"):
                try:
                    modified_para_ids.add(int(p.attrib.get("id", "-1")))
                except Exception:
                    pass
        if "갱신 윈도우:" in full:
            if set_paragraph_text(p, f"갱신 윈도우: {new_window}"):
                try:
                    modified_para_ids.add(int(p.attrib.get("id", "-1")))
                except Exception:
                    pass
        if "갱신 윈도우 확인:" in full:
            if set_paragraph_text(p, f"갱신 윈도우 확인: {new_window}"):
                try:
                    modified_para_ids.add(int(p.attrib.get("id", "-1")))
                except Exception:
                    pass
        if "가격 메모:" in full:
            if set_paragraph_text(p, f"가격 메모: {updates['note']}"):
                try:
                    modified_para_ids.add(int(p.attrib.get("id", "-1")))
                except Exception:
                    pass

    # Table cell normalization for band / escalation.
    for tr in root.iter(f"{{{HP_NS}}}tr"):
        tcs = [tc for tc in tr if tc.tag == f"{{{HP_NS}}}tc"]
        if len(tcs) < 2:
            continue

        def tc_first_paragraph(tc: ET.Element) -> ET.Element | None:
            for p in tc.iter(f"{{{HP_NS}}}p"):
                return p
            return None

        left_text = "".join((t.text or "") for t in tcs[0].iter(f"{{{HP_NS}}}t")).strip()
        if left_text == "가격 밴드":
            p = tc_first_paragraph(tcs[1])
            if p is not None:
                if set_paragraph_text(p, updates["band"]):
                    try:
                        modified_para_ids.add(int(p.attrib.get("id", "-1")))
                    except Exception:
                        pass
        if left_text == "에스컬레이션 연락처":
            p = tc_first_paragraph(tcs[1])
            if p is not None:
                if set_paragraph_text(p, updates["escalation_email"]):
                    try:
                        modified_para_ids.add(int(p.attrib.get("id", "-1")))
                    except Exception:
                        pass

    # Follow-up replacement (only when this section contains the follow-up area).
    if followups_rows is not None:
        followup_items = [r.get("item", "").strip() for r in followups_rows if (r.get("item") or "").strip()]

        # Find the "후속 조치" heading paragraph, then consecutive numbered follow-ups.
        ps = iter_paragraphs(root)
        heading_idx = None
        for i, p in enumerate(ps):
            if paragraph_full_text(p).strip() == "후속 조치":
                heading_idx = i
                break

        if heading_idx is not None:
            # Collect existing consecutive numbered paragraphs.
            numbered = []
            j = heading_idx + 1
            while j < len(ps):
                txt = paragraph_full_text(ps[j]).strip()
                if re.match(r"^\d+\.\s", txt):
                    numbered.append(ps[j])
                    j += 1
                    continue
                break

            if numbered:
                # Determine template and insertion position.
                template = numbered[0]
                parent = None
                # Find parent element that directly contains these <hp:p> (root in our fixture).
                for cand in root.iter():
                    if any(ch is template for ch in list(cand)):
                        parent = cand
                        break
                if parent is None:
                    parent = root

                # Ensure we can compute ids for new paragraphs when adding.
                existing_ids = []
                for p in root.iter(f"{{{HP_NS}}}p"):
                    if "id" in p.attrib:
                        try:
                            existing_ids.append(int(p.attrib["id"]))
                        except Exception:
                            pass
                next_id = (max(existing_ids) + 1) if existing_ids else 1000

                # Adjust count: add or remove paragraphs to match followup_items.
                if len(followup_items) > len(numbered):
                    # Insert new paragraphs after the last numbered one.
                    last = numbered[-1]
                    insert_pos = list(parent).index(last) + 1
                    for _ in range(len(followup_items) - len(numbered)):
                        new_p = deepcopy(template)
                        new_p.attrib["id"] = str(next_id)
                        next_id += 1
                        # Clear any layout cache; will be re-removed later anyway.
                        remove_layout_caches_from_paragraph(new_p)
                        parent.insert(insert_pos, new_p)
                        insert_pos += 1
                        numbered.append(new_p)

                elif len(followup_items) < len(numbered):
                    # Remove extra paragraphs from the end.
                    for extra in numbered[len(followup_items):]:
                        parent.remove(extra)
                    numbered = numbered[: len(followup_items)]

                # Now set the numbered paragraph texts.
                for idx, (p, item) in enumerate(zip(numbered, followup_items), start=1):
                    new_line = f"{idx}. {item}"
                    if set_paragraph_text(p, new_line):
                        try:
                            modified_para_ids.add(int(p.attrib.get("id", "-1")))
                        except Exception:
                            pass

    # Remove layout caches for modified paragraphs.
    for p in root.iter(f"{{{HP_NS}}}p"):
        try:
            pid = int(p.attrib.get("id", "-999999"))
        except Exception:
            continue
        if pid in modified_para_ids:
            remove_layout_caches_from_paragraph(p)

    tree.write(xml_path, xml_declaration=True, encoding="UTF-8")


def extract_hwpx(src_hwpx: str, extract_dir: str) -> None:
    if os.path.exists(extract_dir):
        shutil.rmtree(extract_dir)
    os.makedirs(extract_dir, exist_ok=True)

    with zipfile.ZipFile(src_hwpx, "r") as z:
        z.extractall(extract_dir)


def make_hwpx(extract_dir: str, out_hwpx: str) -> None:
    if os.path.exists(out_hwpx):
        os.remove(out_hwpx)

    # Walk and add files with stable ordering.
    all_files = []
    for root, dirs, files in os.walk(extract_dir):
        dirs.sort()
        files.sort()
        for f in files:
            p = os.path.join(root, f)
            rel = os.path.relpath(p, extract_dir)
            all_files.append((rel, p))

    with zipfile.ZipFile(out_hwpx, "w") as z:
        # Some formats require 'mimetype' first and uncompressed.
        mimetype = next((p for rel, p in all_files if rel == "mimetype"), None)
        if mimetype is not None:
            z.write(mimetype, arcname="mimetype", compress_type=zipfile.ZIP_STORED)

        for rel, p in all_files:
            if rel == "mimetype":
                continue
            z.write(p, arcname=rel, compress_type=zipfile.ZIP_DEFLATED)


def main() -> None:
    if not os.path.exists(SRC_HWPX):
        die(f"missing {SRC_HWPX}")
    if not os.path.exists(UPDATE_JSON):
        die(f"missing {UPDATE_JSON}")
    if not os.path.exists(FOLLOWUPS_CSV):
        die(f"missing {FOLLOWUPS_CSV}")

    updates = load_updates()
    followups_rows = load_followups()

    # Extract
    extract_hwpx(SRC_HWPX, EXTRACT_DIR)

    sec0 = os.path.join(EXTRACT_DIR, "Contents", "section0.xml")
    if not os.path.exists(sec0):
        die("Contents/section0.xml not found in HWPX")
    update_section_xml(sec0, updates, followups_rows=None)

    # Follow-ups appear in section1.xml in this playbook fixture; update it if present.
    sec1 = os.path.join(EXTRACT_DIR, "Contents", "section1.xml")
    if os.path.exists(sec1):
        update_section_xml(sec1, updates, followups_rows=followups_rows)

    # Repackage
    make_hwpx(EXTRACT_DIR, OUT_HWPX)

    # Minimal sanity check
    if not zipfile.is_zipfile(OUT_HWPX):
        die("output is not a valid zip")

    print(f"Wrote {OUT_HWPX}")


if __name__ == "__main__":
    main()
